package inertia

import (
	"html/template"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// scaffoldRoot is the root document generated by andurel new. It must stay in
// sync with layout/templates/resources_root_html.tmpl.
const scaffoldRoot = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">{{if not .SSR}}<title>{{.ProjectName}}</title>{{end}}{{.SSRHead}}{{.ViteHead}}</head><body class="bg-background text-foreground">{{if .SSR}}{{.SSRBody}}{{else}}{{.PageScript}} {{.AppMount}}{{end}}{{.ViteBody}}</body></html>
{{- /* trim the final newline so the response matches the previous root document */ -}}
`

func parseTestRoot(t *testing.T, document string) *template.Template {
	t.Helper()
	return template.Must(template.New("root.html").Parse(document))
}

func TestScaffoldRootMatchesPreviousDocument(t *testing.T) {
	var document strings.Builder
	err := parseTestRoot(t, scaffoldRoot).Execute(&document, RootData{
		ProjectName: "Project & Co",
		ContainerID: "app",
		PageJSON:    []byte(`{"component":"Home","props":{"value":"</script>"}}`),
		ViteHead:    template.HTML(`<script type="module" src="/head.js"></script>`),
		ViteBody:    template.HTML(`<script type="module" src="/body.js"></script>`),
	})
	if err != nil {
		t.Fatalf("Execute: %v", err)
	}

	want := `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Project &amp; Co</title><script type="module" src="/head.js"></script></head><body class="bg-background text-foreground"><script data-page="app" type="application/json">{"component":"Home","props":{"value":"\u003c\/script\u003e"}}</script> <div id="app"></div><script type="module" src="/body.js"></script></body></html>`
	if got := document.String(); got != want {
		t.Fatalf("root document mismatch\n got: %q\nwant: %q", got, want)
	}
}

func TestPageScriptEscapesBreakoutVectors(t *testing.T) {
	pageJSON := []byte(`{"value":"</script><script>alert(1)</script>","comment":"<!--","line":"\u2028\u2029"}`)
	output, err := (RootData{ContainerID: "app", PageJSON: pageJSON}).PageScript()
	if err != nil {
		t.Fatalf("PageScript: %v", err)
	}
	if strings.Contains(string(output), "</script><script>") ||
		strings.Contains(string(output), "<!--") {
		t.Fatalf("page script contains an unescaped breakout: %s", output)
	}
	if got := strings.Count(string(output), "</script>"); got != 1 {
		t.Fatalf("page script has %d closing script tags, want 1: %s", got, output)
	}
	for _, escaped := range []string{`\u003c\/script\u003e`, `\u003c!--`, `\u2028`, `\u2029`} {
		if !strings.Contains(string(output), escaped) {
			t.Fatalf("page script did not escape %q: %s", escaped, output)
		}
	}
}

func TestPageScriptEscapesContainerID(t *testing.T) {
	containerID := `"><script>alert(1)</script>`
	if output := string((RootData{ContainerID: containerID}).AppMount()); strings.Contains(output, "<script>") ||
		!strings.Contains(output, "&lt;script&gt;") {
		t.Fatalf("mount element did not escape the container ID: %s", output)
	}

	script, err := (RootData{ContainerID: containerID, PageJSON: []byte(`{}`)}).PageScript()
	if err != nil {
		t.Fatalf("PageScript: %v", err)
	}
	if strings.Contains(string(script), `<script>alert`) ||
		!strings.Contains(string(script), "&#34;&gt;&lt;script&gt;") {
		t.Fatalf("page script did not escape the container ID: %s", script)
	}
}

func TestSSRHelpersAreNilSafe(t *testing.T) {
	data := RootData{}
	if got := string(data.SSRHead()); got != "" {
		t.Fatalf("SSRHead rendered %q for a nil response", got)
	}
	if got := string(data.SSRBody()); got != "" {
		t.Fatalf("SSRBody rendered %q for a nil response", got)
	}
}

func TestScaffoldRootSSRDocument(t *testing.T) {
	var document strings.Builder
	err := parseTestRoot(t, scaffoldRoot).Execute(&document, RootData{
		ProjectName: "Project",
		ContainerID: "app",
		PageJSON:    []byte(`{"component":"Home"}`),
		ViteHead:    template.HTML(`<link rel="stylesheet" href="/app.css">`),
		ViteBody:    template.HTML(`<script type="module" src="/app.js"></script>`),
		SSR: &SSRResponse{
			Head: []string{"<title>SSR</title>", `<meta name="ssr" content="true">`},
			Body: `<div data-server-rendered="true" data-page="app">SSR</div>`,
		},
	})
	if err != nil {
		t.Fatalf("Execute: %v", err)
	}

	want := `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>SSR</title>` + "\n" + `<meta name="ssr" content="true"><link rel="stylesheet" href="/app.css"></head><body class="bg-background text-foreground"><div data-server-rendered="true" data-page="app">SSR</div><script type="module" src="/app.js"></script></body></html>`
	if got := document.String(); got != want {
		t.Fatalf("SSR root document mismatch\n got: %q\nwant: %q", got, want)
	}
	if strings.Contains(document.String(), "<title>Project</title>") {
		t.Fatalf("SSR root kept the static fallback title: %s", document.String())
	}
}

func TestWithRootFuncRendersCustomDocument(t *testing.T) {
	var calls int
	renderer, err := newTestRenderer(WithRootFunc(func(writer io.Writer, _ RootData) error {
		calls++
		_, err := io.WriteString(writer, "custom")
		return err
	}))
	if err != nil {
		t.Fatalf("NewRenderer: %v", err)
	}

	request := httptest.NewRequest(http.MethodGet, "/", nil)
	recorder := httptest.NewRecorder()
	if err := renderer.Page(testContext(request, recorder), "Home", nil).Render(); err != nil {
		t.Fatalf("Render: %v", err)
	}
	if calls != 1 || recorder.Body.String() != "custom" {
		t.Fatalf("calls=%d body=%q, want one custom root render", calls, recorder.Body.String())
	}
}

func TestWithRootRejectsNil(t *testing.T) {
	if _, err := newTestRenderer(WithRoot(nil)); err == nil {
		t.Fatal("expected a nil root template error")
	}
	if _, err := newTestRenderer(WithRootFunc(nil)); err == nil {
		t.Fatal("expected a nil root renderer error")
	}
}

func TestWithRootRendersRootData(t *testing.T) {
	root := parseTestRoot(t, scaffoldRoot)
	renderer, err := newTestRenderer(WithRoot(root))
	if err != nil {
		t.Fatalf("NewRenderer: %v", err)
	}

	request := httptest.NewRequest(http.MethodGet, "/", nil)
	recorder := httptest.NewRecorder()
	if err := renderer.Page(testContext(request, recorder), "Home", Props{"value": "hello"}).Render(); err != nil {
		t.Fatalf("Render: %v", err)
	}
	if body := recorder.Body.String(); !strings.Contains(body, `"value":"hello"`) ||
		!strings.Contains(body, `<div id="app"></div>`) {
		t.Fatalf("template root render missing data: %s", body)
	}
}
